long long parallel_sum(const std::vector<int>& v, unsigned nthreads) {
  if (nthreads == 0) nthreads = 1;
  const size_t n = v.size();
  std::vector<long long> partial(nthreads, 0);
  std::vector<std::thread> ts;
  ts.reserve(nthreads);
  for (unsigned i = 0; i < nthreads; ++i) {
    size_t lo = n * i / nthreads;
    size_t hi = n * (i + 1) / nthreads;
    ts.emplace_back([&v, &partial, i, lo, hi] {
      long long s = 0;            // local accumulator: no false sharing
      for (size_t k = lo; k < hi; ++k) s += v[k];
      partial[i] = s;             // single write at the end
    });
  }
  for (auto& t : ts) t.join();    // join gives happens-before for partial[]
  long long total = 0;
  for (long long p : partial) total += p;
  return total;
}

